(async()=>{if(!new URLSearchParams(location.search).get('profile')?.startsWith('underground-check'))throw Error('Use the separate underground-check profile for this test.');const wait=ms=>new Promise(r=>setTimeout(r,ms));while(!window.EmberQA)await wait(200);const q=EmberQA,W=EmberTerrain,output=document.createElement('section');output.id='caveCheck';output.style='position:fixed;inset:0;z-index:10000;background:#142124;color:white;overflow:auto;padding:20px;font:14px monospace';document.body.append(output);const report=document.createElement('pre');report.id='report';output.append(report);document.getElementById('welcome').hidden=true;q.close();q.setPlaying(false);
 const result={ready:true,caves:W.caves.length,walk:[],pictures:[],paths:[],brightness:{}};
 const snapshot=q.snapshot();async function view(c,s,label,u=0,reverse=false){const p=W.cavePoint(c,u,s),v=structuredClone(snapshot);Object.assign(v,p,{y:W.caveFloor(c,u,s),yaw:Math.atan2(-c.fx,-c.fz)+(reverse?Math.PI:0),pitch:s<0?0:-.1});q.apply(v);await wait(500);q.renderer.render(q.scene,q.camera);const im=document.createElement('img');im.id=label;im.alt=label;im.style='width:49%;display:inline-block';im.src=q.renderer.domElement.toDataURL('image/png');output.append(im);result.pictures.push(label);}
 for(const c of W.caves){const p=W.cavePoint(c,0,-2),v=structuredClone(snapshot);Object.assign(v,p,{y:W.caveFloor(c,0,-2),yaw:Math.atan2(-c.fx,-c.fz),pitch:0});q.apply(v);q.keys({KeyW:true});for(let n=0;n<180;n++)q.move(1/60);q.keys({});const pos=W.caveLocal(c,q.state.x,q.state.z);q.keys({KeyS:true});for(let n=0;n<180;n++)q.move(1/60);q.keys({});result.walk.push({id:c.id,s:Math.round(pos.s*10)/10,exit:Math.round(W.caveLocal(c,q.state.x,q.state.z).s*10)/10});}
 for(const c of W.caves){let failures=[];for(const path of c.paths.slice(1)){const first=path[0],p=W.cavePoint(c,first[0],first[1]),v=structuredClone(snapshot);Object.assign(v,p,{y:W.caveFloor(c,...first),yaw:0});q.apply(v);for(const target of path.slice(1)){const to=W.cavePoint(c,target[0],target[1]),limit=Math.ceil(Math.hypot(to.x-q.state.x,to.z-q.state.z)/7*30)+30;q.keys({KeyW:true});for(let n=0;n<limit;n++){const dx=to.x-q.state.x,dz=to.z-q.state.z;if(Math.hypot(dx,dz)<.2)break;q.state.yaw=Math.atan2(-dx,-dz);q.move(1/30);}q.keys({});if(Math.hypot(to.x-q.state.x,to.z-q.state.z)>.4)failures.push(target);}}result.paths.push({id:c.id,failures});}
 q.inventory();for(const level of[40,140]){const slider=document.getElementById('caveBrightness');slider.value=level;slider.dispatchEvent(new Event('input',{bubbles:true}));result.brightness[level]=q.snapshot().caveBrightness;}q.close();
 await view(W.caves[0],-2,'entrance');await view(W.caves[0],12,'inside');await view(W.caves[0],21,'deep');await view(W.caves[0],14,'exit',0,true);snapshot.caveBrightness=40;await view(W.caves[0],33,'dark',6);snapshot.caveBrightness=140;await view(W.caves[0],33,'light',6);const saved=q.snapshot();saved.checkpoint={id:'qa-camp',x:saved.x,y:saved.y,z:saved.z};q.apply(saved);result.saved=q.saveSlot(19);q.apply(SurvivalData.fresh());q.loadSlot(19);q.setPlaying(false);q.close();result.reloaded={brightness:q.state.caveBrightness,underground:q.state.y<W.ground(q.state.x,q.state.z)-3};report.textContent=JSON.stringify(result,null,2);document.title='洞窟確認完了';})().catch(e=>{document.body.insertAdjacentHTML('beforeend','<pre id="report">'+e.stack+'</pre>');});
